lock table public.world_characters in access exclusive mode;
do $c$ declare d text; begin
  select string_agg(x, ', ') into d from (
    select i.item_name x from public.world_item_catalog i where i.item_name in (select jsonb_array_elements_text($J$["종이배 쏘가리","종이배 쏘가리 매운탕","종이배 쏘가리 탁본","잠긴 종루 메기","종루 메기 찜","잠긴 종루 메기 탁본","월영 유리송어","유리송어 회","월영 유리송어 탁본","밀수꾼 금눈돔","금눈돔 소금구이","밀수꾼 금눈돔 탁본","거울 얼음 곤들매기","얼음 곤들매기 탕","거울 얼음 곤들매기 탁본","잠든 용왕 철갑상어","용왕 비늘 환","잠든 용왕 철갑상어 탁본","혜성꼬리 만새기","혜성 만새기 구이","혜성꼬리 만새기 탁본","잔불 등불아귀","잔불 쓸개 환","잔불 등불아귀 탁본","잿빛 수염 메기","잿빛 메기 약선","잿빛 수염 메기 탁본"]$J$::jsonb)) and i.item_id not in (select jsonb_array_elements_text($J$["paperboat_mandarin","paperboat_spicy_stew","hf_rubbing_paperboat_mandarin","belltower_catfish","belltower_catfish_steam","hf_rubbing_belltower_catfish","moonglass_trout","moonglass_sashimi","hf_rubbing_moonglass_trout","smuggler_alfonsino","alfonsino_salt_grill","hf_rubbing_smuggler_alfonsino","mirror_ice_char","ice_char_broth","hf_rubbing_mirror_ice_char","sleeping_king_sturgeon","sturgeon_scale_pill","hf_rubbing_sleeping_king_sturgeon","comet_dolphinfish","comet_dolphinfish_grill","hf_rubbing_comet_dolphinfish","ember_lantern_angler","ember_gall_pill","hf_rubbing_ember_lantern_angler","ashwhisker_catfish","ashwhisker_herbal_soup","hf_rubbing_ashwhisker_catfish"]$J$::jsonb))
    union all select s.fish_name from public.world_fish_species s where s.fish_name in (select jsonb_array_elements_text($J$["종이배 쏘가리","잠긴 종루 메기","월영 유리송어","밀수꾼 금눈돔","거울 얼음 곤들매기","잠든 용왕 철갑상어","혜성꼬리 만새기","잔불 등불아귀","잿빛 수염 메기"]$J$::jsonb)) and s.fish_id not in (select jsonb_array_elements_text($J$["paperboat_mandarin","belltower_catfish","moonglass_trout","smuggler_alfonsino","mirror_ice_char","sleeping_king_sturgeon","comet_dolphinfish","ember_lantern_angler","ashwhisker_catfish"]$J$::jsonb))
    union all select t.title_name from public.world_title_catalog t where t.title_name in (select jsonb_array_elements_text($J$["종이배를 낚은 이","종루를 낚은 이","달그림자를 낚은 이","금눈을 낚은 이","얼음 거울을 낚은 이","용왕을 깨운 이","혜성을 낚은 이","잔불을 낚은 이","잿빛 수염을 낚은 이","온 나라의 명어를 낚은 이"]$J$::jsonb)) and t.title_key not in (select jsonb_array_elements_text($J$["nf_paperboat_mandarin","nf_belltower_catfish","nf_moonglass_trout","nf_smuggler_alfonsino","nf_mirror_ice_char","nf_sleeping_king_sturgeon","nf_comet_dolphinfish","nf_ember_lantern_angler","nf_ashwhisker_catfish","nf_named_all"]$J$::jsonb))
    union all select g.ground_name from public.world_fish_grounds g where false) q;
  if d is not null then raise exception '이름 겹침: %', d; end if;
  if (select count(*) from public.world_fish_grounds g where (g.region_id, g.habitat) in (select x.ground, x.habitat from jsonb_to_recordset($J$[{"fish_id":"paperboat_mandarin","fish_name":"종이배 쏘가리","habitat":"river","phase":"dawn","weather":"clear","min_level":3,"size_min":30,"size_max":70,"description":"등의 무늬가 접은 종이배처럼 겹친 쏘가리. 맑은 해돋이에 백지교 아래로 떠내려 온 강물고기 냄새를 따라 올라온다더라.","ground":"paper_bridge","n":1},{"fish_id":"belltower_catfish","fish_name":"잠긴 종루 메기","habitat":"canal","phase":"night","weather":"rain","min_level":5,"size_min":50,"size_max":120,"description":"물에 잠긴 옛 종루 밑에 산다는 메기. 장우 내리는 삼경이면 수염으로 종을 건드려 울린다더라.","ground":"sunken_district","n":2},{"fish_id":"moonglass_trout","fish_name":"월영 유리송어","habitat":"lake","phase":"night","weather":"clear","min_level":10,"size_min":40,"size_max":90,"description":"비늘이 유리처럼 비쳐 달그림자가 몸 안에 떠 보이는 송어. 맑은 삼경에 못물고기 냄새를 맡고 떠오른다더라.","ground":"glass_canyon","n":3},{"fish_id":"smuggler_alfonsino","fish_name":"밀수꾼 금눈돔","habitat":"sea","phase":"dusk","weather":"fog","min_level":9,"size_min":30,"size_max":60,"description":"눈이 금화처럼 번쩍이는 돔. 안개 낀 땅거미에 밀수 부두 아래로 바닷물고기 냄새를 따라 숨어든다더라.","ground":"hidden_bazaar","n":4},{"fish_id":"mirror_ice_char","fish_name":"거울 얼음 곤들매기","habitat":"lake","phase":"dawn","weather":"snow","min_level":13,"size_min":40,"size_max":90,"description":"비늘이 얼음 거울처럼 하늘을 비추는 곤들매기. 설한 내리는 해돋이에 얼음 구멍 아래로 못물고기 냄새를 따라온다더라.","ground":"sky_lake","n":5},{"fish_id":"sleeping_king_sturgeon","fish_name":"잠든 용왕 철갑상어","habitat":"deep","phase":"noon","weather":"drizzle","min_level":14,"size_min":120,"size_max":260,"description":"수궁 회랑에서 잠든 용왕을 지킨다는 철갑상어. 세우 내리는 한낮이면 깊은 물고기 냄새에 눈을 뜬다더라.","ground":"sunken_palace","n":6},{"fish_id":"comet_dolphinfish","fish_name":"혜성꼬리 만새기","habitat":"sea","phase":"night","weather":"clear","min_level":25,"size_min":80,"size_max":180,"description":"꼬리지느러미가 혜성 꼬리처럼 빛을 끄는 만새기. 맑은 삼경, 별빛 벼랑 아래로 바닷물고기 냄새를 좇아 든다더라.","ground":"star_observatory","n":7},{"fish_id":"ember_lantern_angler","fish_name":"잔불 등불아귀","habitat":"abyss","phase":"dusk","weather":"cloudy","min_level":28,"size_min":60,"size_max":140,"description":"머리에 꺼지지 않는 잔불을 매단 아귀. 담운 낀 땅거미에 심연 물고기 냄새를 맡고 균열 가까이 올라온다더라.","ground":"black_tide_rift","n":8},{"fish_id":"ashwhisker_catfish","fish_name":"잿빛 수염 메기","habitat":"marsh","phase":"night","weather":"fog","min_level":30,"size_min":70,"size_max":160,"description":"수염 끝에 재가 엉겨 붙은 늪 메기. 농무 낀 삼경에 늪물고기 냄새를 따라 갈대 여울로 나온다더라.","ground":"ash_reeds","n":9}]$J$::jsonb) as x(ground text, habitat text))) <> 9 then
    raise exception '낚시터가 없는 명어 자리가 있습니다';
  end if;
  if exists (select 1 from jsonb_array_elements_text($J$["abyss_angler","ash_lanternfish","black_rockfish","bullhead","canal_carp","canal_eel","cherry_salmon","croaker","dace","ghost_goby","gizzard_shad","ink_greenling","inkdot_bitterling","lake_trout","lenok","mackerel","minnow","nameless_angler","palace_lanternfish","palace_puffer","pond_smelt","reed_crucian","sea_eel","silver_scale","snakehead","spanish_mackerel","swamp_eel","sweetfish","void_hagfish","well_blindfish","yellowtail"]$J$::jsonb) b where not exists (select 1 from public.world_fish_species s where s.fish_id = b)) then
    raise exception '없는 미끼 물고기가 있습니다';
  end if;
end $c$;
insert into public.world_item_catalog(item_id, item_name, category, tier, description, stackable, required_stats, minimum_level, rarity, acquisition_difficulty, drop_rate_modifier, equipment_traits, tradeable, reference_price, stack_size, use_fx)
select x.item_id, x.item_name, x.category, x.tier, x.description, x.stackable, x.required_stats, x.minimum_level, x.rarity, x.acquisition_difficulty, x.drop_rate_modifier, x.equipment_traits, x.tradeable, x.reference_price, x.stack_size, x.use_fx from jsonb_to_recordset($J$[{"item_id":"paperboat_mandarin","item_name":"종이배 쏘가리","category":"material","tier":5,"description":"이름을 지킨 물고기, 명어(名魚). 등의 무늬가 접은 종이배처럼 겹친 쏘가리. 맑은 해돋이에 백지교 아래로 떠내려 온 강물고기 냄새를 따라 올라온다더라.","stackable":true,"required_stats":{},"minimum_level":1,"rarity":"legendary","acquisition_difficulty":5,"drop_rate_modifier":1,"equipment_traits":{},"tradeable":false,"reference_price":300,"stack_size":20,"use_fx":null},{"item_id":"paperboat_spicy_stew","item_name":"종이배 쏘가리 매운탕","category":"consumable","tier":3,"description":"종이배 쏘가리를 맵게 끓였다. 체력과 정신을 채우고 든든하다.","stackable":true,"required_stats":{},"minimum_level":1,"rarity":"rare","acquisition_difficulty":3,"drop_rate_modifier":1,"equipment_traits":{},"tradeable":false,"reference_price":270,"stack_size":20,"use_fx":{"er":0,"hp":30,"mn":10,"sp":0,"stam":0,"buffs":["well_fed"],"cures":[]}},{"item_id":"hf_rubbing_paperboat_mandarin","item_name":"종이배 쏘가리 탁본","category":"furniture","tier":4,"description":"별채 가구 · 족자. 별채에 놓으면 가방에서 빠지고, 거두면 곳간으로 갑니다.","stackable":false,"required_stats":{},"minimum_level":1,"rarity":"epic","acquisition_difficulty":4,"drop_rate_modifier":1,"equipment_traits":{"hk":"rubbing_paperboat_mandarin","kind":"wall","wall":"deco","ww":2.2,"wh":30,"cat":"족자","grade":4},"tradeable":false,"reference_price":800,"stack_size":1,"use_fx":null},{"item_id":"belltower_catfish","item_name":"잠긴 종루 메기","category":"material","tier":5,"description":"이름을 지킨 물고기, 명어(名魚). 물에 잠긴 옛 종루 밑에 산다는 메기. 장우 내리는 삼경이면 수염으로 종을 건드려 울린다더라.","stackable":true,"required_stats":{},"minimum_level":1,"rarity":"legendary","acquisition_difficulty":5,"drop_rate_modifier":1,"equipment_traits":{},"tradeable":false,"reference_price":300,"stack_size":20,"use_fx":null},{"item_id":"belltower_catfish_steam","item_name":"종루 메기 찜","category":"consumable","tier":3,"description":"잠긴 종루 메기를 쪄 냈다. 정신이 맑아져 단서가 잘 보인다.","stackable":true,"required_stats":{},"minimum_level":1,"rarity":"rare","acquisition_difficulty":3,"drop_rate_modifier":1,"equipment_traits":{},"tradeable":false,"reference_price":270,"stack_size":20,"use_fx":{"er":0,"hp":25,"mn":15,"sp":0,"stam":0,"buffs":["clear_mind"],"cures":[]}},{"item_id":"hf_rubbing_belltower_catfish","item_name":"잠긴 종루 메기 탁본","category":"furniture","tier":4,"description":"별채 가구 · 족자. 별채에 놓으면 가방에서 빠지고, 거두면 곳간으로 갑니다.","stackable":false,"required_stats":{},"minimum_level":1,"rarity":"epic","acquisition_difficulty":4,"drop_rate_modifier":1,"equipment_traits":{"hk":"rubbing_belltower_catfish","kind":"wall","wall":"deco","ww":2.2,"wh":30,"cat":"족자","grade":4},"tradeable":false,"reference_price":800,"stack_size":1,"use_fx":null},{"item_id":"moonglass_trout","item_name":"월영 유리송어","category":"material","tier":5,"description":"이름을 지킨 물고기, 명어(名魚). 비늘이 유리처럼 비쳐 달그림자가 몸 안에 떠 보이는 송어. 맑은 삼경에 못물고기 냄새를 맡고 떠오른다더라.","stackable":true,"required_stats":{},"minimum_level":1,"rarity":"legendary","acquisition_difficulty":5,"drop_rate_modifier":1,"equipment_traits":{},"tradeable":false,"reference_price":380,"stack_size":20,"use_fx":null},{"item_id":"moonglass_sashimi","item_name":"유리송어 회","category":"consumable","tier":3,"description":"월영 유리송어를 얇게 떴다. 정신을 채우고 감각이 예리해진다.","stackable":true,"required_stats":{},"minimum_level":1,"rarity":"rare","acquisition_difficulty":3,"drop_rate_modifier":1,"equipment_traits":{},"tradeable":false,"reference_price":340,"stack_size":20,"use_fx":{"er":0,"hp":0,"mn":30,"sp":0,"stam":0,"buffs":["keen_senses"],"cures":[]}},{"item_id":"hf_rubbing_moonglass_trout","item_name":"월영 유리송어 탁본","category":"furniture","tier":4,"description":"별채 가구 · 족자. 별채에 놓으면 가방에서 빠지고, 거두면 곳간으로 갑니다.","stackable":false,"required_stats":{},"minimum_level":1,"rarity":"epic","acquisition_difficulty":4,"drop_rate_modifier":1,"equipment_traits":{"hk":"rubbin