  craft_field = excluded.craft_field, minimum_level = excluded.minimum_level, description = excluded.description, recipe_difficulty = excluded.recipe_difficulty;
update public.world_item_catalog i set reference_price = greatest(i.reference_price,
    ceil(1.1 * (select min(t.v) from (select sum(m.reference_price * (x.value)::int * 1.0 / greatest(1, cr.output_qty)) v from public.world_crafting_recipes cr, jsonb_each_text(cr.ingredients) x
      join public.world_item_catalog m on m.item_id = x.key where cr.output_item = i.item_id group by cr.recipe_id) t)))
 where i.item_id in (select jsonb_array_elements_text($J$["paperboat_spicy_stew","hf_rubbing_paperboat_mandarin","belltower_catfish_steam","hf_rubbing_belltower_catfish","moonglass_sashimi","hf_rubbing_moonglass_trout","alfonsino_salt_grill","hf_rubbing_smuggler_alfonsino","ice_char_broth","hf_rubbing_mirror_ice_char","sturgeon_scale_pill","hf_rubbing_sleeping_king_sturgeon","comet_dolphinfish_grill","hf_rubbing_comet_dolphinfish","ember_gall_pill","hf_rubbing_ember_lantern_angler","ashwhisker_herbal_soup","hf_rubbing_ashwhisker_catfish"]$J$::jsonb));
insert into public.world_item_catalog(item_id, item_name, category, tier, description, stackable, required_stats, required_job, required_faction, minimum_level,
  rarity, acquisition_difficulty, drop_rate_modifier, equipment_traits, crafting_specialization, tradeable, reference_price, stack_size, base_item_id, quality_grade, use_fx)
select i.item_id || '_hq', i.item_name || ' (우수)', i.category, i.tier, i.description || ' ' || public.world_item_hq_note(i.item_id, i.category), i.stackable,
  i.required_stats, i.required_job, i.required_faction, i.minimum_level, i.rarity, i.acquisition_difficulty, i.drop_rate_modifier, i.equipment_traits,
  i.crafting_specialization, i.tradeable, ceil(coalesce(i.reference_price, 0) * 1.3), i.stack_size, i.item_id, 1, null
  from public.world_item_catalog i
 where i.item_id in (select jsonb_array_elements_text($J$["paperboat_spicy_stew","belltower_catfish_steam","moonglass_sashimi","alfonsino_salt_grill","ice_char_broth","sturgeon_scale_pill","comet_dolphinfish_grill","ember_gall_pill","ashwhisker_herbal_soup"]$J$::jsonb))
on conflict (item_id) do nothing;
insert into public.world_fish_species(fish_id, fish_name, habitat, rarity, min_level, phase, weather, size_min, size_max, description, sort, active, grounds, bait_for, named)
select x.fish_id, x.fish_name, x.habitat, 'legendary', x.min_level, x.phase, x.weather, x.size_min, x.size_max, x.description,
       (select coalesce(max(sort), 0) from public.world_fish_species) + x.n, true, array[x.ground], '{}'::text[], true
  from jsonb_to_recordset($J$[{"fish_id":"paperboat_mandarin","fish_name":"종이배 쏘가리","habitat":"river","phase":"dawn","weather":"clear","min_level":3,"size_min":30,"size_max":70,"description":"등의 무늬가 접은 종이배처럼 겹친 쏘가리. 맑은 해돋이에 백지교 아래로 떠내려 온 강물고기 냄새를 따라 올라온다더라.","ground":"paper_bridge","n":1},{"fish_id":"belltower_catfish","fish_name":"잠긴 종루 메기","habitat":"canal","phase":"night","weather":"rain","min_level":5,"size_min":50,"size_max":120,"description":"물에 잠긴 옛 종루 밑에 산다는 메기. 장우 내리는 삼경이면 수염으로 종을 건드려 울린다더라.","ground":"sunken_district","n":2},{"fish_id":"moonglass_trout","fish_name":"월영 유리송어","habitat":"lake","phase":"night","weather":"clear","min_level":10,"size_min":40,"size_max":90,"description":"비늘이 유리처럼 비쳐 달그림자가 몸 안에 떠 보이는 송어. 맑은 삼경에 못물고기 냄새를 맡고 떠오른다더라.","ground":"glass_canyon","n":3},{"fish_id":"smuggler_alfonsino","fish_name":"밀수꾼 금눈돔","habitat":"sea","phase":"dusk","weather":"fog","min_level":9,"size_min":30,"size_max":60,"description":"눈이 금화처럼 번쩍이는 돔. 안개 낀 땅거미에 밀수 부두 아래로 바닷물고기 냄새를 따라 숨어든다더라.","ground":"hidden_bazaar","n":4},{"fish_id":"mirror_ice_char","fish_name":"거울 얼음 곤들매기","habitat":"lake","phase":"dawn","weather":"snow","min_level":13,"size_min":40,"size_max":90,"description":"비늘이 얼음 거울처럼 하늘을 비추는 곤들매기. 설한 내리는 해돋이에 얼음 구멍 아래로 못물고기 냄새를 따라온다더라.","ground":"sky_lake","n":5},{"fish_id":"sleeping_king_sturgeon","fish_name":"잠든 용왕 철갑상어","habitat":"deep","phase":"noon","weather":"drizzle","min_level":14,"size_min":120,"size_max":260,"description":"수궁 회랑에서 잠든 용왕을 지킨다는 철갑상어. 세우 내리는 한낮이면 깊은 물고기 냄새에 눈을 뜬다더라.","ground":"sunken_palace","n":6},{"fish_id":"comet_dolphinfish","fish_name":"혜성꼬리 만새기","habitat":"sea","phase":"night","weather":"clear","min_level":25,"size_min":80,"size_max":180,"description":"꼬리지느러미가 혜성 꼬리처럼 빛을 끄는 만새기. 맑은 삼경, 별빛 벼랑 아래로 바닷물고기 냄새를 좇아 든다더라.","ground":"star_observatory","n":7},{"fish_id":"ember_lantern_angler","fish_name":"잔불 등불아귀","habitat":"abyss","phase":"dusk","weather":"cloudy","min_level":28,"size_min":60,"size_max":140,"description":"머리에 꺼지지 않는 잔불을 매단 아귀. 담운 낀 땅거미에 심연 물고기 냄새를 맡고 균열 가까이 올라온다더라.","ground":"black_tide_rift","n":8},{"fish_id":"ashwhisker_catfish","fish_name":"잿빛 수염 메기","habitat":"marsh","phase":"night","weather":"fog","min_level":30,"size_min":70,"size_max":160,"description":"수염 끝에 재가 엉겨 붙은 늪 메기. 농무 낀 삼경에 늪물고기 냄새를 따라 갈대 여울로 나온다더라.","ground":"ash_reeds","n":9}]$J$::jsonb) as x(fish_id text, fish_name text, habitat text, min_level int, phase text, weather text, size_min numeric, size_max numeric, description text, ground text, n int)
on conflict (fish_id) do update set fish_name = excluded.fish_name, habitat = excluded.habitat, rarity = excluded.rarity, min_level = excluded.min_level, phase = excluded.phase,
  weather = excluded.weather, size_min = excluded.size_min, size_max = excluded.size_max, description = excluded.description, grounds = excluded.grounds, named = excluded.named;
update public.world_fish_species s set bait_for = array(select distinct unnest(s.bait_for || array(select jsonb_array_elements_text($J${"minnow":["paperboat_mandarin"],"dace":["paperboat_mandarin"],"sweetfish":["paperboat_mandarin"],"bullhead":["paperboat_mandarin"],"canal_carp":["belltower_catfish"],"canal_eel":["belltower_catfish"],"ghost_goby":["belltower_catfish"],"pond_smelt":["moonglass_trout"],"lake_trout":["moonglass_trout","mirror_ice_char"],"cherry_salmon":["moonglass_trout","mirror_ice_char"],"gizzard_shad":["smuggler_alfonsino"],"black_rockfish":["smuggler_alfonsino"],"sea_eel":["smuggler_alfonsino"],"ink_greenling":["smuggler_alfonsino"],"lenok":["mirror_ice_char"],"palace_puffer":["sleeping_king_sturgeon"],"palace_lanternfish":["sleeping_king_sturgeon"],"well_blindfish":["sleeping_king_sturgeon"],"silver_scale":["sleeping_king_sturgeon"],"yellowtail":["comet_dolphinfish"],"spanish_mackerel":["comet_dolphinfish"],"croaker":["comet_dolphinfish"],"mackerel":["comet_dolphinfish"],"void_hagfish":["ember_lantern_angler"],"abyss_angler":["ember_lantern_angler"],"ash_lanternfish":["ember_lantern_angler"],"nameless_angler":["ember_lantern_angler"],"snakehead":["ashwhisker_catfish"],"swamp_eel":["ashwhisker_catfish"],"reed_crucian":["ashwhisker_catfish"],"inkdot_bitterling":["ashwhisker_catfish"]}$J$::jsonb -> s.fish_id))) order by 1)
 where s.fish_id in (select jsonb_object_keys($J${"minnow":["paperboat_mandarin"],"dace":["paperboat_mandarin"],"sweetfish":["paperboat_mandarin"],"bullhead":["paperboat_mandarin"],"canal_carp":["belltower_catfish"],"canal_eel":["belltower_catfish"],"ghost_goby":["belltower_catfish"],"pond_smelt":["moonglass_trout"],"lake_trout":["moonglass_trout","mirror_ice_char"],"cherry_salmon":["moonglass_trout","mirror_ice_char"],"gizzard_shad":["smuggler_alfonsino"],"black_rockfish":["smuggler_alfonsino"],"sea_eel":["smuggler_alfonsino"],"ink_greenling":["smuggler_alfonsino"],"lenok":["mirror_ice_char"],"palace_puffer":["sleeping_king_sturgeon"],"palace_lanternfish":["sleeping_king_sturgeon"],"well_blindfish":["sleeping_king_sturgeon"],"silver_scale":["sleeping_king_sturgeon"],"yellowtail":["comet_dolphinfish"],"spanish_mackerel":["comet_dolphinfish"],"croaker":["comet_dolphinfish"],"mackerel":["comet_dolphinfish"],"void_hagfish":["ember_lantern_angler"],"abyss_angler":["ember_lantern_angler"],"ash_lanternfish":["ember_lantern_angler"],"nameless_angler":["ember_lantern_angler"],"snakehead":["ashwhisker_catfish"],"swamp_eel":["ashwhisker_catfish"],"reed_crucian":["ashwhisker_catfish"],"inkdot_bitterling":["ashwhisker_catfish"]}$J$::jsonb));
do $c$ begin
  if exists (select 1 from public.world_fish_species n where n.named and (select count(*) from public.world_fish_species b where n.fish_id = any (b.bait_for) and b.rarity in ('common', 'uncommon', 'rare')) < 3) then
    raise exception '명어마다 미끼가 셋 이상이어야 합니다';
  end if;
end $c$;
insert into public.world_title_catalog(title_key, title_name, description, condition_text, bonus, hidden, rule, sort, category, grade)
select x.title_key, x.title_name, x.cond || '.', '숨겨진 조건', x.bonus, x.hidden, x.rule, 150 + x.n, '낚시', x.grade
  from jsonb_to_recordset($J$[{"title_key":"nf_paperboat_mandarin","title_name":"종이배를 낚은 이","grade":3,"bonus":{"fish_bite_pct":2},"rule":{"n":1,"p":{"fish":"paperboat_mandarin"},"ev":"fish"},"cond":"종이배 쏘가리을(를) 낚는다","hidden":true,"n":1},{"title_key":"nf_belltower_catfish","title_name":"종루를 낚은 이","grade":3,"bonus":{"clue_bonus_pct":2},"rule":{"n":1,"p":{"fish":"belltower_catfish"},"ev":"fish"},"cond":"잠긴 종루 메기을(를) 낚는다","hidden":true,"n":2},{"title_key":"nf_moonglass_trout","title_name":"달그림자를 낚은 이","grade":3,"bonus":{"rare_loot_pct":2},"rule":{"n":1,"p":{"fish":"moonglass_trout"},"ev":"fish"},"cond":"월영 유리송어을(를) 낚는다","hidden":true,"n":3},{"title_key":"nf_smuggler_alfonsino","title_name":"금눈을 낚은 이","grade":3,"bonus":{"fish_rare_pct":2},"rule":{"n":1,"p":{"fish":"smuggler_alfonsino"},"ev":"fish"},"cond":"밀수꾼 금눈돔을(를) 낚는다","hidden":true,"n":4},{"title_key":"nf_mirror_ice_char","title_name":"얼음 거울을 낚은 이","grade":3,"bonus":{"mental_loss_pct":-2},"rule":{"n":1,"p":{"fish":"mirror_ice_char"},"ev":"fish"},"cond":"거울 얼음 곤들매기을(를) 낚는다","hidden":true,"n":5},{"title_key":"nf_sleeping_king_sturgeon","title_name":"용왕을 깨운 이","grade":3,"bonus":{"incoming_damage_pct":-1},"rule":{"n":1,"p":{"fish":"sleeping_king_sturgeon"},"ev":"fish"},"cond":"잠든 용왕 철갑상어을(를) 낚는다","hidden":true,"n":6},{"title_key":"nf_comet_dolphinfish","title_name":"혜성을 낚은 이","grade":4,"bonus":{"gather_qty_pct":3},"rule":{"n":1,"p":{"fish":"comet_dolphinfish"},"ev":"fish"},"cond":"혜성꼬리 만새기을(를) 낚는다","hidden":true,"n":7},{"title_key":"nf_ember_lantern_angler","title_name":"잔불을 낚은 이","grade":4,"bonus":{"erosion_pct":-3},"rule":{"n":1,"p":{"fish":"ember_lantern_angler"},"ev":"fish"},"cond":"잔불 등불아귀을(를) 낚는다","hidden":true,"n":8},{"title_key":"nf_ashwhisker_catfish","title_name":"잿빛 수염을 낚은 이","grade":4,"bonus":{"fish_size_pct":4},"rule":{"n":1,"p":{"fish":"ashwhisker_catfish"},"ev":"fish"},"cond":"잿빛 수염 메기을(를) 낚는다","hidden":true,"n":9},{"title_key":"nf_named_all","title_name":"온 나라의 명어를 낚은 이","grade":5,"bonus":{"fish_bite_pct":5,"fish_rare_pct":8,"gather_qty_pct":3},"rule":{"all":[{"p":{"fish":"paperboat_mandarin"},"ev":"fish"},{"p":{"fish":"belltower_catfish"},"ev":"fish"},{"p":{"fish":"moonglass_trout"},"ev":"fish"},{"p":{"fish":"smuggler_alfonsino"},"ev":"fish"},{"p":{"fish":"mirror_ice_char"},"ev":"fish"},{"p":{"fish":"sleeping_king_sturgeon"},"ev":"fish"},{"p":{"fish":"comet_dolphinfish"},"ev":"fish"},{"p":{"fish":"ember_lantern_angler"},"ev":"fish"},{"p":{"fish":"ashwhisker_catfish"},"ev":"fish"}]},"cond":"대세력 땅과 중립 땅의 명어 아홉을 모두 낚는다","hidden":true,"n":10}]$J$::jsonb) as x(title_key text, title_name text, grade int, bonus jsonb, rule jsonb, cond text, hidden boolean, n int)
on conflict (title_key) do update set title_name = excluded.title_name, description = excluded.description, condition_text = excluded.condition_text, bonus = excluded.bonus,
  hidden = excluded.hidden, rule = excluded.rule, category = excluded.category, grade = excluded.grade;
update public.world_patch_notes set body = replace(body, E'- 명어와 명어로 만든 음식·가구·낚싯대는 거래할 수 없습니다.\n', $N$- 묵적록 밖에도 명어 아홉이 삽니다. 대세력 땅마다 하나(정통파 침수 골목 웅덩이 · 적월교 월영 유리못 · 흑련회 십삼문 밀수 부두 · 북령맹 천경호 얼음 구멍 · 수향연맹 수궁 잠긴 회랑 · 천명원 관성대 별빛 벼랑 · 남명회 흑조 균열 물가)와 중립 땅 둘(백지교 아래 여울 · 잿빛 갈대 여울)입니다. 묵적록 명어처럼 정해진 시간대·날씨에 그 물 물고기를 미끼로 걸어야 물고, 낚시터 레벨에 맞춰 일찍부터 노릴 수 있습니다.
- 새 명어마다 음식이나 약 하나와 탁본 액자(별채 가구), 숨김 칭호가 있고, 아홉을 모두 낚으면 칭호가 하나 더 있습니다.
- 명어와 명어로 만든 음식·가구·낚싯대는 거래할 수 없습니다.
$N$) where note_id = '2.0.0' and position('묵적록 밖에도 명어 아홉' in body) = 0;
update public.world_patch_notes set body = body || $N$

## 그 밖
- 휴대폰 싸움 화면(봉연·파티 토벌·귀허·먹그림자)에서 채팅 동그라미를 기록 손잡이 아래 손잡이로 옮겨, 협동 기술 칸을 가리지 않게 했습니다.
$N$ where note_id = '2.0.0' and position('채팅 동그라미를 기록 손잡이 아래' in body) = 0;

select public.world_quest_label_refresh();
insert into public.world_app_meta(key, value, changed_at) values ('db_version', '20261116040000', now())
on conflict (key) do update set value = excluded.value, changed_at = excluded.changed_at;
